// Captions.kt
//
// Turning a video's captions into lyrics: which track to use, and its cues as LRC lines.

package com.music.innertube

import com.music.innertube.models.response.PlayerResponse.Captions.CaptionTrack
import kotlinx.serialization.json.Json
import kotlinx.serialization.json.contentOrNull
import kotlinx.serialization.json.jsonArray
import kotlinx.serialization.json.jsonObject
import kotlinx.serialization.json.jsonPrimitive
import kotlinx.serialization.json.longOrNull
import java.util.Locale

/**
 * The auto-generated track, or an uploaded one in the same language when there is one. The
 * auto-generated track is what says which language the song is sung in: a video's uploaded tracks
 * are as often translations, and a translation is not the lyrics. With no auto-generated track
 * there is nothing to tell them apart by, so nothing is picked.
 */
internal fun pickCaptionTrack(tracks: List<CaptionTrack>): CaptionTrack? {
    val auto = tracks.firstOrNull { it.isAutoGenerated } ?: return null
    val language = auto.languageCode?.substringBefore('-')
    return tracks.firstOrNull { !it.isAutoGenerated && it.languageCode?.substringBefore('-') == language }
        ?: auto
}

/**
 * Timed-text JSON (fmt=json3) as LRC, one line per caption. Auto-generated captions put each
 * line's words in one event and the line breaks in events of their own, which carry no text and
 * drop out. Sound labels like "[Music]" and note signs are not words, and go.
 */
internal fun timedTextToLrc(json: String): String {
    val events = Json.parseToJsonElement(json).jsonObject["events"]?.jsonArray ?: return ""
    val lines = ArrayList<String>()
    var previous: String? = null
    for (event in events) {
        val cue = event.jsonObject
        val start = cue["tStartMs"]?.jsonPrimitive?.longOrNull ?: continue
        val segs = cue["segs"]?.jsonArray ?: continue
        val text = segs.joinToString("") { it.jsonObject["utf8"]?.jsonPrimitive?.contentOrNull.orEmpty() }
            .replace(SoundLabel, " ")
            .replace('♪', ' ')
            .replace(Whitespace, " ")
            .trim()
        // a rolling caption repeats its line as the next one scrolls in
        if (text.isEmpty() || text == previous) continue
        previous = text
        lines += String.format(Locale.ROOT, "[%02d:%02d.%03d]%s", start / 60_000, start / 1000 % 60, start % 1000, text)
    }
    return lines.joinToString("\n")
}

private val SoundLabel = Regex("""\[[^\]]*]""")
private val Whitespace = Regex("""\s+""")
